(()=>{'use strict';const $=id=>document.getElementById(id),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),colors=['#f0a060','#77b8dd','#c2a2e8','#e87f70'];let data,q,asset='equity',n=20,selected=new Set(),currentReport=null,notes='';
function invalidate(){currentReport=null;$('report').innerHTML='<div class="empty-state">材料或选项已变化，请重新组装对照解读。</div>';$('export').disabled=$('exportHtml').disabled=true;$('notice').textContent='';}
function allEvents(){return data.events}
function updateCatalogue(){const term=$('search').value.trim().toLowerCase(),month=$('timelineMonth').value;const rows=allEvents().filter(e=>(!month||e.date.startsWith(month))&&(!term||(e.title+' '+e.date+' '+e.fact+' '+e.tool).toLowerCase().includes(term))).sort((a,b)=>b.date.localeCompare(a.date));$('poolCount').textContent=`显示 ${rows.length} / ${allEvents().length} 个节点 · 由近及远`;let previous='';$('events').innerHTML=rows.map(e=>{const m=e.date.slice(0,7),heading=m!==previous?`<div class="timeline-month">${esc(m)}</div>`:'';previous=m;return heading+`<button class="event-row ${q?.id===e.id?'selected':''}" aria-pressed="${q?.id===e.id}" data-event="${esc(e.id)}"><small>${esc(e.date)}</small>${esc(e.title)}</button>`}).join('')||'<p class="muted">该时间范围没有已收录的事件；可清除筛选或查看其他月份。</p>'}
function candidates(){return allEvents().filter(c=>Lens.match(q,c).eligible).sort((a,b)=>(Lens.match(q,a).rank||9)-(Lens.match(q,b).rank||9)||b.date.localeCompare(a.date)).slice(0,8)}
function choose(id){q=allEvents().find(e=>e.id===id);if(!q)return;notes='';selected=new Set(candidates().slice(0,2).map(c=>c.id));$('confirm').checked=false;invalidate();updateCatalogue();renderFact();renderCases();renderChart();updateAssemble();try{const u=new URL(location.href);u.searchParams.set('event',q.id);history.replaceState(null,'',u)}catch{}}
function renderFact(){$('eventTitle').textContent=q.title;$('fact').textContent=q.fact;$('verification').textContent=q.verification;$('eventMeta').innerHTML=`<div><span>记录的事件日</span>${esc(q.eventDate)}</div><div><span>首次公开日期</span>${esc(q.firstPublicDate||'尚未核实')}</div><div><span>具体工具 / 发布主题</span>${esc(q.tool)}</div><div><span>主体 / 地区</span>${esc(q.subject)} · ${esc(q.region)}</div><div><span>阶段 / 统计期</span>${esc(({decision:'政策决定',data_release:'数据发布',announcement:'政策宣布',implementation:'政策实施',operation:'政策操作',communication:'政策沟通',other_occurrence:'其他事件'})[q.stage]||q.stage)} · ${esc(q.period||'不适用/未记录')}</div><div><span>预期差</span>未知 · 无一致预期数据</div><div class="wide"><span>时间对齐约定</span>${esc(q.timeNote)} 构造序列取 ≥ ${esc(q.anchor)} 的首个演示点。</div>`;$('sourceCount').textContent=`（${q.sources.length}）`;$('sources').innerHTML=q.sources.map((s,i)=>`<article class="source"><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">[E${i+1}] ${esc(s.title)} ↗</a><p>${esc(s.publisher)} · 资料发布 ${esc(s.publicationDate||'未知')}</p><p>${esc(s.role)} · ${esc(s.status)}</p></article>`).join('');}
function renderCases(){const rows=candidates();$('caseCount').textContent=`${rows.length} 条候选 / 已选 ${selected.size}`;$('cases').innerHTML=rows.length?rows.map(c=>`<article class="case ${selected.has(c.id)?'checked':''}"><label><input type="checkbox" data-case="${esc(c.id)}" ${selected.has(c.id)?'checked':''}>${esc(c.date)}</label><h3>${esc(c.title)}</h3><p class="basis">${esc(Lens.match(q,c).reason)}</p><p class="difference">关键差异：${esc(Lens.match(q,c).difference||'')} ${esc(c.notes)} ${c.period&&q.period?`统计期 ${esc(c.period)} / ${esc(q.period)}。`:''}</p><p class="muted">${esc(c.verification)} · ${c.sources.length} 个来源</p><button class="quiet" data-case-source="${esc(c.id)}">查看事实与来源</button><div id="case-source-${esc(c.id)}" hidden></div></article>`).join(''):'<div class="empty-state">当前资料中没有满足可比条件的先前案例。可选择其他事件；不会按标题或涨跌凑案例。</div>';$('rejected').innerHTML=allEvents().filter(c=>c.group===q.group&&c.id!==q.id&&!Lens.match(q,c).eligible).slice(-12).map(c=>`<p>${esc(c.date)} · ${esc(c.title)}<br>未入选：${esc(Lens.match(q,c).reason)}</p>`).join('')||'<p>没有其他同类记录。</p>';}
function chosen(){return candidates().filter(c=>selected.has(c.id))}
function series(){return [q,...chosen()].map((event,i)=>({event,result:Lens.observe(data.assets[asset],event.anchor,n),color:colors[i%colors.length]}))}
function renderChart(){const a=data.assets[asset],rows=series();document.querySelectorAll('[data-asset]').forEach(b=>b.classList.toggle('selected',b.dataset.asset===asset));$('priceMeta').textContent=`${a.name}（构造示例；${a.unit}）· 生成日期轴截止 ${a.last} · ${a.limitations}`;$('legend').innerHTML=rows.map((r,i)=>`<span><i style="background:${r.color}"></i>${i===0?'当前':'历史'} ${esc(r.event.date)} · 演示</span>`).join('');$('metrics').innerHTML=rows.map(r=>{const x=r.result;return `<tr><td>${esc(r.event.title)}<br>${esc(r.event.date)}</td><td>${x.base?esc(x.base.date)+'<br>'+x.base.close.toFixed(2):'—'}</td><td>${x.end?esc(x.end.date)+'<br>'+x.end.close.toFixed(2):'—'}</td><td class="${x.value>=0?'positive':'negative'}">${x.value===null?'—':(x.value>0?'+':'')+x.value.toFixed(2)+'%'} <small>演示变化</small></td><td>${esc(x.status==='complete'?'完整演示窗口':x.reason)}<br>${x.count}/${n} 个点</td></tr>`}).join('');draw(rows);}
function draw(rows){const usable=rows.filter(r=>r.result.path.length),pts=usable.flatMap(r=>r.result.path);if(!pts.length){$('chart').innerHTML='<div class="empty-state">该构造演示窗口无可用值，未生成走势图。</div>';return}const W=800,H=280,L=52,R=20,T=20,B=35,minX=Math.min(-20,...pts.map(p=>p.t)),maxX=n,minY=Math.min(-.2,...pts.map(p=>p.value)),maxY=Math.max(.2,...pts.map(p=>p.value)),pad=(maxY-minY)*.12,lo=minY-pad,hi=maxY+pad,x=t=>L+(t-minX)/(maxX-minX)*(W-L-R),y=v=>T+(hi-v)/(hi-lo)*(H-T-B);let out=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="构造示例价格路径，基准归零，横轴为构造点数"><title>非市场行情的构造示例，基准=0%</title>`;for(let i=0;i<5;i++){const v=lo+(hi-lo)*i/4;out+=`<line x1="${L}" x2="${W-R}" y1="${y(v)}" y2="${y(v)}" stroke="var(--chart-grid)"/><text x="${L-8}" y="${y(v)+4}" text-anchor="end" font-size="11" fill="var(--chart-muted)">${v.toFixed(1)}%</text>`}out+=`<line x1="${x(0)}" x2="${x(0)}" y1="${T}" y2="${H-B}" stroke="var(--chart-baseline)" stroke-dasharray="4 4"/><text x="${x(0)+5}" y="${T+10}" font-size="10" fill="var(--chart-label)">演示基准</text>`;for(const t of [-20,-10,0,...(n===20?[10,20]:[n])])out+=`<text x="${x(t)}" y="${H-10}" text-anchor="middle" font-size="11" fill="var(--chart-muted)">${t>0?'+':''}${t}</text>`;for(const r of usable){const path=r.result.path.map((p,i)=>(i?'L':'M')+x(p.t).toFixed(2)+' '+y(p.value).toFixed(2)).join(' ');out+=`<path d="${path}" fill="none" stroke="${r.color}" stroke-width="${r.event.id===q.id?2.7:1.8}" stroke-opacity=".95"/>`}out+='</svg>';$('chart').innerHTML=out;}
function updateAssemble(){$('assemble').disabled=!$('confirm').checked||selected.size===0;}
function renderReport(r){const rows=r.results.map((x,i)=>{const a=x.result;return `<li>[P${i+1}] ${esc(x.event.date)} · ${a.value===null?esc(a.reason)+'，不计算':`${esc(a.base.date)} ${a.base.close.toFixed(2)} → ${esc(a.end.date)} ${a.end.close.toFixed(2)}；${a.value.toFixed(2)}%`}（构造示例）。</li>`}).join('');$('report').innerHTML=`<div class="report-section"><h3><span class="label">事实</span>本次研究对象</h3><p>${esc(r.facts)} [E1] ${esc(q.verification)}</p></div><div class="report-section"><h3><span class="label">演示计算</span>${esc(data.assets[r.assetKey].name)} · ${r.n}个构造观测</h3><p>以下日期窗与价格由构造样例演算，不能用于历史行情分析。</p><ul>${rows}</ul><p>结果只展示日期对齐与确定性计算，不表示实际市场表现，也与对应事件无关。</p></div><div class="report-section"><h3><span class="label">AI 离线预研</span>相似依据与关键差异</h3><p>${esc(r.shared)}</p><p>${esc(r.difference)}</p><ul>${chosen().map(c=>`<li>${esc(c.date)}：${esc(Lens.match(q,c).reason)}。${esc(Lens.match(q,c).difference)} ${esc(c.notes)} ${esc(c.verification)}。</li>`).join('')}</ul></div><div class="report-section"><h3><span class="label">研究推断 · 待验证</span>一种可能的传导解释</h3><p>${esc(r.hypothesis)}</p><p>这是一项研究假设；当前材料未验证因果关系。</p></div><div class="report-section"><h3>不确定性与数据缺口</h3><ul>${r.limits.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p>${esc(data.assets[r.assetKey].limitations)}</p></div><div class="report-section"><h3>本次引用</h3>${r.sources.map((s,i)=>`<p>[E${i+1}] <a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)}</a> · ${esc(s.role)} · ${esc(s.status)}</p>`).join('')}</div><label>我的修订与待核事项<textarea id="researchNotes" class="research-notes" rows="3" maxlength="4000" placeholder="写下你不同意的解释、需要补查的来源…">${esc(notes)}</textarea></label><p class="muted">报告组装时间 ${esc(new Date(r.createdAt).toLocaleString('zh-CN'))} · 事件资料准备 ${esc(data.preparedAt)}。未进行在线模型调用；行情采用构造数据。</p>`;}
function assemble(){if(!$('confirm').checked||!chosen().length)return;currentReport=Lens.report(data,q,chosen(),asset,n);renderReport(currentReport);$('export').disabled=$('exportHtml').disabled=false;$('notice').textContent='已按当前案例与窗口组装；你可以修订并导出。';}
function capture(){return {...currentReport,title:q.title,notes:$('researchNotes')?.value||'',queryEvent:q,caseEvents:chosen(),asset:data.assets[asset].name,dataPreparedAt:data.preparedAt,marketDataMode:data.marketDataMode,method:'离线AI预研片段 + 构造价格示例的确定性演算；不含真实历史行情或在线模型调用'}}
function download(name,body,type){const blob=new Blob([body],{type}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),3000)}
function exportHtml(r){const content=$('report').innerHTML.replace(/<textarea[\s\S]*?<\/textarea>/,'<p>'+esc(r.notes)+'</p>');download('以事为镜研究简报.html',`<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="color-scheme" content="dark"><title>${esc(r.title)}</title><style>body{max-width:850px;margin:40px auto;padding:20px;font:15px/1.8 system-ui;color:#e8e5df;background:#111314}h3{border-bottom:1px solid #34383a;padding-bottom:8px}.label{font-size:11px;color:#f0a060}a{color:#f0a060;overflow-wrap:anywhere}</style><h1>${esc(r.title)}</h1><p>${esc(r.method)}</p>${content}</html>`,'text/html;charset=utf-8')}
function activateStep(active){document.querySelectorAll('.steps .step').forEach((link,index)=>{const current=index===active;link.classList.toggle('active',current);if(current)link.setAttribute('aria-current','step');else link.removeAttribute('aria-current')})}
function syncSteps(){const ids=['workspace','step-cases','step-prices','step-report'],nav=document.querySelector('.steps'),line=Math.max((nav?.getBoundingClientRect().bottom||0)+24,Math.min(window.innerHeight*.28,240));let active=0;ids.forEach((id,index)=>{const section=$(id);if(section&&section.getBoundingClientRect().top<=line)active=index});if(window.scrollY+window.innerHeight>=document.documentElement.scrollHeight-8)active=3;activateStep(active)}
let stepFrame=0;window.addEventListener('scroll',()=>{if(!stepFrame)stepFrame=requestAnimationFrame(()=>{syncSteps();stepFrame=0})},{passive:true});window.addEventListener('resize',syncSteps);document.querySelectorAll('.steps .step').forEach((link,index)=>link.addEventListener('click',()=>activateStep(index)));
document.addEventListener('click',ev=>{
  const b=ev.target.closest('button');
  if(!b)return;
  if(b.dataset.event)choose(b.dataset.event);
  if(b.dataset.asset){asset=b.dataset.asset;invalidate();renderChart()}
  if(b.dataset.caseSource){
    const c=allEvents().find(e=>e.id===b.dataset.caseSource),el=$('case-source-'+c.id);
    el.hidden=!el.hidden;
    el.innerHTML=`<p>${esc(c.fact)}</p>${c.sources.map(s=>`<p><a target="_blank" rel="noopener noreferrer" href="${esc(s.url)}">${esc(s.title)} ↗</a><br>${esc(s.status)}</p>`).join('')}`;
  }
});
document.addEventListener('change',ev=>{if(ev.target.dataset.case){if(ev.target.checked)selected.add(ev.target.dataset.case);else selected.delete(ev.target.dataset.case);invalidate();renderCases();renderChart();updateAssemble()}});
 $('search').addEventListener('input',updateCatalogue);$('timelineMonth').onchange=updateCatalogue;$('clearTimeline').onclick=()=>{$('search').value='';$('timelineMonth').value='';updateCatalogue()};$('confirm').onchange=updateAssemble;$('window').onchange=()=>{n=Number($('window').value);invalidate();renderChart()};$('assemble').onclick=assemble;$('export').onclick=()=>download('以事为镜研究.json',JSON.stringify(capture(),null,2),'application/json');$('exportHtml').onclick=()=>exportHtml(capture());
fetch('data.json').then(r=>{if(!r.ok)throw Error('资料文件读取失败：'+r.status);return r.json()}).then(d=>{if(!d.events?.length||!d.assets?.gold||!d.assets?.equity)throw Error('资料格式或行情字段不完整');if(d.marketDataMode?.type!=='synthetic_demo'||Object.values(d.assets).some(a=>a.synthetic!==true))throw Error('行情模式未声明为构造演示，已停止显示，避免把未知行情误标为示意数据');data=d;$('eventCount').textContent=d.events.length;$('dataLimits').textContent=d.coverage+' '+d.rights;$('loading').hidden=true;$('workspace').hidden=false;const id=new URL(location.href).searchParams.get('event');choose(d.events.some(e=>e.id===id)?id:'RECENT-20260909-PRICES');syncSteps()}).catch(e=>{$('loading').hidden=true;$('error').hidden=false;$('error').textContent='研究资料暂不可用。'+e.message+'。没有生成替代行情或AI结论。请刷新重试。'});
})();
